import Foundation
import Darwin

private struct HealthFixtureFailure: Error { let label: String }
private var checks = 0
private func expect(_ condition: @autoclosure () throws -> Bool, _ label: String) throws { checks += 1; if try !condition() { throw HealthFixtureFailure(label: label) } }
private func rejected(_ label: String, _ operation: () throws -> Void) throws { do { try operation() } catch { checks += 1; return }; throw HealthFixtureFailure(label: label) }
private let owner = "11111111-1111-4111-8111-111111111111", deviceID = "22222222-2222-4222-8222-222222222222"
private let key = "alf_" + String(repeating: "x", count: 24)
private let at = Date(timeIntervalSince1970: 1_800_000_000)
private func config() -> CollectorConfig { CollectorConfig(version: 1, key: key, senderAllowlist: ["mobilemoney"]) }
private func binding() -> CollectorAccountBinding { CollectorAccountBinding(version: 1, identity: CollectorAccountIdentity(ownerId: owner, preferredName: "Fictional reviewer", email: "private-fixture@example.invalid"), credentialHash: config().credentialHash, confirmedAt: stamp(at)) }
private func device() -> CollectorHealthDevice { CollectorHealthDevice(version: 1, deviceId: deviceID, ownerId: owner) }
private func status(quarantine: Int64 = 0, unreadable: Int64 = 0, incomplete: Int64 = 0, held: Int64 = 0, pending: Int64 = 0, capture: String? = stamp(at)) -> OutboxStatus {
    OutboxStatus(initializedAt: "2020-01-01T00:00:00.000Z", lastCapturedRowID: 777, lastSuccessfulCaptureAt: capture, sourceScanHasMore: false,
        pendingCount: pending, heldForReviewCount: held, sourceQuarantineCount: quarantine, unreadableSourceCount: unreadable,
        incompleteSourceMetadataCount: incomplete, firstQuarantinedSourceRowID: 888, sourceRetryAttempts: 9, acknowledgedCount: 29,
        failedAttemptCount: 7, lastAcceptedAt: nil, senderAllowlist: ["private-source-fixture"])
}
private func temporary(_ operation: (URL) throws -> Void) throws {
    let root = FileManager.default.temporaryDirectory.appendingPathComponent("alfred-health-fixture-" + UUID().uuidString)
    defer { try? FileManager.default.removeItem(at: root) }; try ensurePrivateDirectory(root); try operation(root)
}
private func statusBytes(_ store: OutboxStore) throws -> Data {
    let encoder = JSONEncoder(); encoder.outputFormatting = [.sortedKeys]
    return try encoder.encode(store.status(config: config()))
}
private func testPrivateDevice() throws {
    try temporary { root in
        var generated = 0
        try rejected("missing device identity never generated by a read") { _ = try loadCollectorHealthDevice(directory: root, ownerId: owner) }
        let prepared = try prepareCollectorHealthDevice(directory: root, ownerId: owner, makeID: { generated += 1; return UUID(uuidString: deviceID)! })
        try expect(prepared.deviceId == deviceID && generated == 1, "explicit setup creates only injected fictional identifier")
        _ = try prepareCollectorHealthDevice(directory: root, ownerId: owner, makeID: { generated += 1; return UUID(uuidString: deviceID)! })
        try expect(generated == 1, "existing identifier preserved without generation")
        let path = root.appendingPathComponent("health-device.json"), raw = try readPrivate(root.appendingPathComponent("health-device.json"))
        var info = stat(); try expect(lstat(path.path, &info) == 0 && info.st_mode & 0o777 == 0o600 && info.st_uid == getuid(), "private owned identifier file")
        try expect(!String(decoding: raw, as: UTF8.self).contains(key), "identifier is not a forwarding credential")
        try rejected("another account cannot reuse or overwrite identifier") { _ = try prepareCollectorHealthDevice(directory: root, ownerId: "33333333-3333-4333-8333-333333333333") }
        try expect(readPrivate(path) == raw, "foreign account check preserves identifier")
        try FileManager.default.setAttributes([.posixPermissions: 0o644], ofItemAtPath: path.path)
        try rejected("public-readable identifier refused") { _ = try loadCollectorHealthDevice(directory: root, ownerId: owner) }
    }
    try temporary { root in
        let target = root.appendingPathComponent("target"), link = root.appendingPathComponent("health-device.json")
        try Data("fictional target".utf8).write(to: target); try FileManager.default.createSymbolicLink(at: link, withDestinationURL: target)
        try rejected("symlink identifier never read or replaced") { _ = try prepareCollectorHealthDevice(directory: root, ownerId: owner) }
        try expect(String(decoding: Data(contentsOf: target), as: UTF8.self) == "fictional target", "symlink target unchanged")
    }
}
private func testCountsAndPrivacy() throws {
    let report = try collectorHealthReport(device: device(), ownerId: owner, status: status(quarantine: 3, unreadable: 1, incomplete: 2, held: 1, pending: 4), captureFailed: false, now: at)
    try expect(report.state == .needsReview && report.counts.sourceQuarantine == 3 && report.counts.unreadable == 1 && report.counts.incomplete == 2 && report.counts.heldForReview == 1 && report.counts.pending == 4, "safe exact aggregate counts")
    let body = try JSONEncoder().encode(report), json = try JSONSerialization.jsonObject(with: body) as! [String: Any]
    try expect(Set(json.keys) == Set(["version", "deviceId", "state", "counts", "lastSuccessfulCaptureAt", "lastAcceptedAt"]), "only permitted health envelope fields")
    try expect(json["lastAcceptedAt"] is NSNull, "unknown acceptance time is explicit null")
    let text = String(decoding: body, as: UTF8.self)
    for forbidden in [key, owner, "private-fixture", "private-source-fixture", "lastCapturedRowID", "firstQuarantinedSourceRowID", "senderAllowlist", "sourceRetryAttempts", "777", "888", "credentialHash", "raw", "guid", "fingerprint", "error"] { try expect(!text.contains(forbidden), "source identifiers, credentials and error strings excluded") }
    try expect(collectorHealthReport(device: device(), ownerId: owner, status: status(), captureFailed: false, now: at).state == .ready, "clean successful capture ready")
    try expect(collectorHealthReport(device: device(), ownerId: owner, status: status(capture: nil), captureFailed: false, now: at).state == .needsReview, "no successful capture is not ready")
    try expect(collectorHealthReport(device: device(), ownerId: owner, status: status(), captureFailed: true, now: at).state == .captureError, "capture failure remains visible after delivery")
    try rejected("count overflow blocked") { _ = try collectorHealthReport(device: device(), ownerId: owner, status: status(pending: 1_000_001), captureFailed: false, now: at) }
    try rejected("negative count blocked") { _ = try collectorHealthReport(device: device(), ownerId: owner, status: status(pending: -1), captureFailed: false, now: at) }
    try rejected("inconsistent source category counts blocked") { _ = try collectorHealthReport(device: device(), ownerId: owner, status: status(quarantine: 1, unreadable: 1, incomplete: 1), captureFailed: false, now: at) }
    try rejected("held count exceeds pending blocked") { _ = try collectorHealthReport(device: device(), ownerId: owner, status: status(held: 1), captureFailed: false, now: at) }
    try rejected("future timestamp blocked") { _ = try collectorHealthReport(device: device(), ownerId: owner, status: status(capture: stamp(at.addingTimeInterval(301))), captureFailed: false, now: at) }
}
private func testBoundedRequestAndAcknowledgement() throws {
    let report = try collectorHealthReport(device: device(), ownerId: owner, status: status(), captureFailed: false, now: at)
    let request = try collectorHealthRequest(report: report, key: key, ownerId: owner, now: at)
    try expect(request.url == collectorHealthURL && request.httpMethod == "POST" && request.timeoutInterval == 2, "fixed HTTPS destination and short request deadline")
    try expect(request.value(forHTTPHeaderField: "X-Alfred-Collector-Owner") == owner, "account assertion header")
    try expect(request.httpBody!.count <= 4096 && !String(decoding: request.httpBody!, as: UTF8.self).contains(key), "bounded counts payload has no key")
    try rejected("invalid key cannot produce a request") { _ = try collectorHealthRequest(report: report, key: "bad", ownerId: owner, now: at) }
    try rejected("invalid owner cannot produce a request") { _ = try collectorHealthRequest(report: report, key: key, ownerId: "bad", now: at) }
    let good = Data("{\"ok\":true}".utf8)
    try expect(collectorHealthAcknowledged(status: 200, data: good, failed: false), "strict check-in acknowledgement")
    for status in [201, 301, 401, 403, 429, 500] { try expect(!collectorHealthAcknowledged(status: status, data: good, failed: false), "other statuses not accepted") }
    for bad in [Data(), Data("{\"ok\":1}".utf8), Data("{\"ok\":false}".utf8), Data(repeating: 32, count: 1025)] { try expect(!collectorHealthAcknowledged(status: 200, data: bad, failed: false), "malformed or oversized check-in acknowledgement refused") }
    try expect(!collectorHealthAcknowledged(status: 200, data: good, failed: true), "network failure refused")
}
private func testBestEffortNeverChangesDataWork() throws {
    try temporary { root in
        let store = try OutboxStore(directory: root); try store.initialize(config: config(), maxRowID: 0, at: Date().addingTimeInterval(-30))
        let message = CapturedMessage(rowID: 1, guid: "fictional-health-guid", sender: "MobileMoney", body: "Fixture payment GHS 25", receivedAt: stamp(), service: "SMS")
        _ = try store.capture(CaptureBatch(messages: [message], lastRowID: 1, hasMore: false), config: config())
        let before = try statusBytes(store)
        var attempts = 0
        try expect(!reportCollectorHealthBestEffort(store: store, config: config(), binding: binding(), directory: root, captureFailed: false, transport: { _, _, _ in attempts += 1; return true }), "missing local status identifier is best-effort failure")
        try expect(attempts == 0 && !pathExists(root.appendingPathComponent("health-device.json")), "runtime reporting never generates an identifier")
        _ = try prepareCollectorHealthDevice(directory: root, ownerId: owner, makeID: { UUID(uuidString: deviceID)! })
        try expect(!reportCollectorHealthBestEffort(store: store, config: config(), binding: binding(), directory: root, captureFailed: true, transport: { report, received, account in attempts += 1; return report.state == .captureError && received == key && account == owner ? false : true }), "health transport failure is isolated")
        try expect(statusBytes(store) == before, "reporting failure never rewinds cursor or deletes pending payload")
        try expect(reportCollectorHealthBestEffort(store: store, config: config(), binding: binding(), directory: root, captureFailed: true, transport: { report, _, _ in report.state == .captureError }), "capture error is reported even with retained data")
        try expect(statusBytes(store) == before && attempts == 1, "health success also leaves financial/outbox state untouched")
    }
}
@main struct CollectorHealthTests {
    static func main() {
        do { try testPrivateDevice(); try testCountsAndPrivacy(); try testBoundedRequestAndAcknowledgement(); try testBestEffortNeverChangesDataWork(); print("PASS: \(checks) synthetic counts-only health assertions; no real device identifier, key, Messages or HTTP used.") }
        catch let failure as HealthFixtureFailure { fputs("FAIL: \(failure.label)\n", stderr); exit(1) }
        catch { fputs("FAIL: synthetic counts-only health fixture operation\n", stderr); exit(1) }
    }
}
